def _get_item_length(item, parents_ids=frozenset([])):
    """
    Get the length of an item for distance calculation purposes.
    This is used to calculate the rough distance between objects.
    """
    if item is None:
        return 0
    if isinstance(item, (str, bytes)):
        return 1
    if isinstance(item, (int, float, complex)):
        return 1
    if isinstance(item, (bool, type(None))):
        return 1
    if isinstance(item, (list, tuple, set, frozenset)):
        if len(item) == 0:
            return 0
        # Check for circular references
        item_id = id(item)
        if item_id in parents_ids:
            return 0
        parents_ids = add_to_frozen_set(parents_ids, item_id)
        total = 0
        for i in item:
            total += _get_item_length(i, parents_ids)
        return total
    if isinstance(item, dict):
        if len(item) == 0:
            return 0
        # Check for circular references
        item_id = id(item)
        if item_id in parents_ids:
            return 0
        parents_ids = add_to_frozen_set(parents_ids, item_id)
        total = 0
        for k, v in item.items():
            total += _get_item_length(k, parents_ids) + _get_item_length(v, parents_ids)
        return total
